<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';require_login();$user=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'create';if($action==='delete'){$id=(int)($_POST['id']??0);$stmt=$pdo->prepare('SELECT template_image FROM twibbons WHERE id=? AND owner_id=?');$stmt->execute([$id,$user['id']]);if($item=$stmt->fetch()){$pdo->prepare('DELETE FROM twibbons WHERE id=? AND owner_id=?')->execute([$id,$user['id']]);$path=__DIR__.'/uploads/'.basename($item['template_image']);if(is_file($path))@unlink($path);flash('success','Karya berhasil dihapus.');}}
else{try{$title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));$tags=trim((string)($_POST['tags']??''));$category=(int)($_POST['category_id']??0);$visibility=in_array($_POST['visibility']??'unlisted',['public','unlisted','private'],true)?$_POST['visibility']:'unlisted';if($title===''||mb_strlen($title)>120)throw new RuntimeException('Judul wajib diisi dan maksimal 120 karakter.');$file=store_image($_FILES['template_image']??[],__DIR__.'/uploads');$moderation=$visibility==='public'?'pending':'approved';$pdo->prepare('INSERT INTO twibbons(slug,owner_id,category_id,visibility,title,description,tags,template_image,moderation_status) VALUES(?,?,?,?,?,?,?,?,?)')->execute([random_slug(),$user['id'],$category?:null,$visibility,$title,$description,$tags,$file,$moderation]);flash('success',$visibility==='public'?'Karya dikirim untuk ditinjau admin.':'Karya berhasil dibuat.');}catch(Throwable $e){flash('error',$e->getMessage());}}header('Location: dashboard');exit;}
$flash=pull_flash();$stmt=$pdo->prepare('SELECT t.*,c.name category_name FROM twibbons t LEFT JOIN categories c ON c.id=t.category_id WHERE t.owner_id=? ORDER BY t.created_at DESC');$stmt->execute([$user['id']]);$items=$stmt->fetchAll();$categories=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$views=array_sum(array_column($items,'view_count'));$uses=array_sum(array_column($items,'use_count'));$downloads=array_sum(array_column($items,'download_count'));
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Studio Kreator — Semarakin</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="teal.css"><link rel="stylesheet" href="auth.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="./"><span class="brand-mark">S</span>Semarakin</a></div></header><main class="container"><div class="page-head dashboard-head"><div><span class="eyebrow">Studio kreator</span><h1 class="page-title" style="margin-top:12px">Halo, <?=e(explode(' ',$user['name'])[0])?>.</h1><p class="subtitle">Buat karya, bangun audiens, dan pantau dampak kampanyemu.</p></div><button class="btn btn-primary" onclick="document.querySelector('#newTemplate').scrollIntoView({behavior:'smooth'})">＋ Karya baru</button></div><?php if($flash):?><div class="alert alert-<?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif?><div class="dashboard-grid"><div class="card stat"><strong><?=compact_number($views)?></strong><span>Total dilihat</span></div><div class="card stat"><strong><?=compact_number($uses)?></strong><span>Digunakan</span></div><div class="card stat"><strong><?=compact_number($downloads)?></strong><span>Diunduh</span></div></div><div class="creator-studio"><section class="panel" id="newTemplate"><div class="form-heading"><span class="form-icon">＋</span><div><h2>Publikasikan karya</h2><p>Lengkapi informasi agar mudah ditemukan.</p></div></div><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label for="title">Judul kampanye</label><input id="title" name="title" maxlength="120" required></div><div class="field"><label for="description">Deskripsi</label><textarea id="description" name="description" rows="3" maxlength="500"></textarea></div><div class="field"><label for="category_id">Kategori</label><select id="category_id" name="category_id" required><option value="">Pilih kategori</option><?php foreach($categories as $cat):?><option value="<?=(int)$cat['id']?>"><?=e($cat['icon'].' '.$cat['name'])?></option><?php endforeach?></select></div><div class="field"><label for="tags">Tag</label><input id="tags" name="tags" maxlength="300" placeholder="sekolah, kemerdekaan, komunitas"></div><div class="field"><label for="visibility">Akses</label><select id="visibility" name="visibility"><option value="public">Publik — ditinjau admin</option><option value="unlisted" selected>Via tautan</option><option value="private">Pribadi</option></select></div><div class="field"><label for="template_image">Bingkai PNG</label><input id="template_image" name="template_image" type="file" accept="image/png,image/jpeg,image/webp" required></div><button class="btn btn-primary" style="width:100%">Simpan karya</button></form></section><section><div class="section-head"><div><h2>Karya saya</h2><p><?=count($items)?> karya tersimpan</p></div></div><div class="studio-list"><?php foreach($items as $item):?><article class="studio-item"><img src="uploads/<?=e(basename($item['template_image']))?>" alt=""><div><span class="visibility visibility-<?=$item['visibility']==='private'?'private':'unlisted'?>"><?=e($item['visibility'])?></span><h3><?=e($item['title'])?></h3><p><?=e($item['category_name']?:'Tanpa kategori')?> · <?=compact_number((int)$item['view_count'])?> dilihat · <?=compact_number((int)$item['use_count'])?> digunakan</p><div class="template-actions"><a class="btn btn-secondary btn-sm" href="t/<?=e($item['slug'])?>">Buka</a><button class="btn btn-secondary btn-sm" onclick="navigator.clipboard.writeText(new URL('t/<?=e($item['slug'])?>',location.href).href)">Salin link</button></div></div><form method="post" data-confirm="Hapus karya ini secara permanen?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button class="btn btn-danger btn-sm">Hapus</button></form></article><?php endforeach?></div><?php if(!$items):?><div class="empty">Belum ada karya. Mulai unggah karya pertamamu.</div><?php endif?></section></div></main><footer class="footer">Semarakin · Produk digital dari Apins Digital</footer></body></html>
